KG42.register("rules-7ca7a37c2f24a60a60bf8fa2",{"id":"49-residential_shared_storage_market::v141-c-R008","paper":"49-residential_shared_storage_market","record":{"rule_id":"v141-c-R008","mechanism_id":"v141-a-M01","name":"Local clearing price","process_stage":"pricing","market_meaning":"Solving the local market equilibrium determines P2P transaction allocations and produces the endogenous bilateral transaction prices. Scope: Bilateral seller–buyer transactions in the proposed local P2P market embedded with residential shared energy storage. The P2P transaction price must be no less than the feed-in tariff plus the P2P transaction cost and no greater than TLOU. Scope: Bilateral P2P transaction prices in the proposed model. No single participant unilaterally controls the P2P clearing price. Scope: The proposed local P2P pricing mechanism.","independence_rationale":"Relations governed by the approved function pricing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","pricing.local"],"E":[{"edge_id":"v141-c-R008-E001","source":"clearing.local","target":"pricing.local","type":"links","constraint_ids":["v141-c-R008-C001"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E23"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Bilateral P2P transaction prices in the proposed model. | Bilateral seller–buyer transactions in the proposed local P2P market embedded with residential shared energy storage. | The proposed local P2P pricing mechanism.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E13","v141-b-g01-E23","v141-b-g03-e03","v141-b-g03-e04"]},"x":[{"variable_id":"v141-c-R008-x-rho","symbol":"\\rho^{t}_{sb}","meaning":"P2P transaction price between seller s and buyer b in period t; the market-clearing price is endogenous to the market equilibrium and is not unilaterally controlled by seller s or buyer b.","kind":"operational","domain":"Endogenous scalar price. The source supplies participation bounds but no explicit set notation: \\rho^{t}_{sb} \\ge \\lambda^{t}_{sell}+\\lambda^{t}_{cost} and \\rho^{t}_{sb} \\le TLOU.","unit":null,"indices":["s","b","t"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E21","v141-b-g02-e024","v141-b-g02-e034","v141-b-g03-e03"]},{"variable_id":"v141-c-R008-x-p","symbol":"p^{t}_{sb}","meaning":"P2P transaction amount between seller s and buyer b in period t; an allocation variable determined together with the P2P transaction price by the market equilibrium.","kind":"operational","domain":"Nonnegative transaction amount; the source imposes p^{t}_{sb}\\ge 0 and \\sum_{b\\in B}p^{t}_{sb}\\le P^{t}_{s} in the seller problem.","unit":null,"indices":["s","b","t"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E12","v141-b-g01-E13","v141-b-g01-E21"]}],"theta":[{"parameter_id":"v141-c-R008-theta-Delta-t","symbol":"\\Delta t","meaning":"Duration of a period, used in the seller-side and buyer-side price decompositions.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E21","v141-b-g02-e034"]},{"parameter_id":"v141-c-R008-theta-lambda-sell","symbol":"\\lambda^{t}_{sell}","meaning":"Feed-in Tariff in period t; lower-bound component for the P2P transaction price.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E21","v141-b-g03-e04"]},{"parameter_id":"v141-c-R008-theta-lambda-cost","symbol":"\\lambda^{t}_{cost}","meaning":"P2P transaction cost in period t, including network tariff for using physical grid facilities and aggregator service fee; lower-bound component for the P2P transaction price.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E21","v141-b-g03-e04"]},{"parameter_id":"v141-c-R008-theta-TLOU","symbol":"\\mathrm{TLOU}","meaning":"Time-and-level-of-use price referenced by the source as the upper bound on the P2P transaction price; the source writes this bound as TLOU without an explicit indexed symbol in the bound statement.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E21","v141-b-g03-e04","v141-b-g02-e008"]}],"phi":[{"constraint_id":"v141-c-R008-C001","kind":"mathematical","role":"core","statement":"Solving the local market equilibrium determines P2P transaction allocations and produces the endogenous bilateral transaction prices. Scope: Bilateral seller–buyer transactions in the proposed local P2P market embedded with residential shared energy storage.","expression":"\\text{Equilibrium (45) determines } p^{t}_{sb} \\text{ and } \\rho^{t}_{sb}, \\text{ with } \\rho^{t}_{sb}=\\lambda^{t}_{sell}+\\lambda^{t}_{cost}+(\\upsilon^{t}_{s}-\\omega^{t}_{sb})/\\Delta t=-\\gamma^{t}_{b}/\\Delta t","formalization_origin":"source","template_id":null,"members":["clearing.local","pricing.local"],"variable_refs":["v141-c-R008-x-rho","v141-c-R008-x-p"],"parameter_refs":["v141-c-R008-theta-Delta-t","v141-c-R008-theta-lambda-sell","v141-c-R008-theta-lambda-cost"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E23","v141-b-g02-e034"]},{"constraint_id":"v141-c-R008-C002","kind":"mathematical","role":"core","statement":"The P2P transaction price must be no less than the feed-in tariff plus the P2P transaction cost and no greater than TLOU. Scope: Bilateral P2P transaction prices in the proposed model.","expression":"\\lambda^{t}_{sell}+\\lambda^{t}_{cost}\\le\\rho^{t}_{sb}\\le \\mathrm{TLOU}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R008-x-rho"],"parameter_refs":["v141-c-R008-theta-lambda-sell","v141-c-R008-theta-lambda-cost","v141-c-R008-theta-TLOU"],"evidence_ids":["v141-b-g01-E13","v141-b-g03-e04"]},{"constraint_id":"v141-c-R008-C003","kind":"mathematical","role":"core","statement":"No single participant unilaterally controls the P2P clearing price. Scope: The proposed local P2P pricing mechanism.","expression":"\\rho^{t}_{sb}=\\lambda^{t}_{sell}+\\lambda^{t}_{cost}+(\\upsilon^{t}_{s}-\\omega^{t}_{sb})/\\Delta t=-\\gamma^{t}_{b}/\\Delta t","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R008-x-rho"],"parameter_refs":["v141-c-R008-theta-Delta-t","v141-c-R008-theta-lambda-sell","v141-c-R008-theta-lambda-cost"],"evidence_ids":["v141-b-g03-e03","v141-b-g02-e034","v141-b-g03-e01","v141-b-g03-e02"]}],"pi":[{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-4c60176b12-p05-c1r4__v141-a-M01-participation","page":5,"printed_page":null,"section":"2.3 Aggregator","anchor_text":"Since the energy buyers use the SES, the allocation of SES use right is also a game. In practice, th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The aggregator collects all participants’ supply and demand information and clears the P2P market. By solving the market equilibrium problem, it can provide P2P transaction price and amount between energy seller and buyer and capacity allocation among energy buyers. The aggregator can facilitate the P2P market and make sure participants benefit from the market."},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-4c60176b12-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1 Seller’s problem","anchor_text":"gy , pi to decision-making problem can be cast as ∑ ∑ ∑ ∑ e. max : ( ρtsbptsb + λtsell(Pts − ptsb) −","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"where p^{t}_{sb} and \\rho^{t}_{sb} are decision variables. p^{t}_{sb} is the transaction amount between seller s and buyer b in period t. \\rho^{t}_{sb} is transaction price associated with p^{t}_{sb}. However, the market-clearing price \\rho^{t}_{sb} is out of control of seller s and buyer b but is determined by the market equilibrium problem of the game. Parameter P^{t}_{s} is the renewable energy for sale of seller s in period t. Parameter \\lambda^{t}_{sell} is FiT when a seller sells its energy to the power grid. Parameter \\lambda^{t}_{cost} is the P2P transaction cost, including network tariff for using the physical grid facilities and aggregator service fee."},{"evidence_id":"v141-b-g01-E23","location":{"location_id":"src-4c60176b12-p04-c2r1__v141-a-M01-coordination","page":4,"printed_page":null,"section":"1.3 Contributions","anchor_text":"Applied Energy 308 (2022) 118400 al 2) A solution method based on Karush-Kuhn-Tucker (KKT) optimalit","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"2) A solution method based on Karush-Kuhn-Tucker (KKT) optimality condition is applied to solve the market equilibrium problem. The market equilibrium is acquired based on the KKT conditions of all participants’ optimal problems. After concatenating all KKT conditions together, the market equilibrium is cast as a mixed-integer linear program (MILP) with the complementarity conditions linearized through the Big-M method. The P2P transaction price and the amount and the SES capacity allocation are obtained from the market equilibrium. The P2P transaction price is determined by the supply and demand relationship and reflects the value of energy resources. Capacity allocation among users can ensure fairness in our definition."},{"evidence_id":"v141-b-g03-e03","location":{"location_id":"src-4c60176b12-p08-c1r1__v141-a-M01-pricing","page":8,"printed_page":null,"section":"4.1 KKT conditions / P2P price","anchor_text":"B. Zheng et al. constraints. The P2P transaction price variable ρtsb is endogenously determined and ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"The price in (46) and (47) are the same in the equilibrium problem (45), and thus the transaction price ρ^{t}_{sb} mainly depends on the parameters and some dual variables. This P2P pricing mechanism is beyond the control of a single participant, and truly reflects the demand and supply relationship and the true value of energy, which is also fair to both sides."},{"evidence_id":"v141-b-g03-e04","location":{"location_id":"src-4c60176b12-p08-c1r2__v141-a-M01-pricing","page":8,"printed_page":null,"section":"4.1 KKT conditions / price bounds","anchor_text":"sb ters and some dual variables. This P2P pricing mechanism is beyond the as control of a single par","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"In addition, in our model, ρ^{t}_{sb} must be no less than the λ^{t}_{sell} + λ^{t}_{cost}, otherwise, sellers will quit the P2P market. Similarly, ρ^{t}_{sb} must be no more than TLOU, otherwise, buyers will quit the P2P market."},{"evidence_id":"v141-b-g01-E11","location":{"location_id":"src-4c60176b12-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1 Seller’s problem","anchor_text":"Applied Energy 308 (2022) 118400 of energy sellers, energy buyers, and market equilibrium are presen","equation_id":"(1)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"For each rational energy seller s ∈ S, it maximizes its profit and the decision-making problem can be cast as\nmax : \\sum_{t\\in T}\\left(\\sum_{b\\in B}\\rho^{t}_{sb}p^{t}_{sb}+\\lambda^{t}_{sell}\\left(P^{t}_{s}-\\sum_{b\\in B}p^{t}_{sb}\\right)-\\lambda^{t}_{cost}\\sum_{b\\in B}p^{t}_{sb}\\right)\\Delta t \\quad (1)"},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-4c60176b12-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1 Seller’s problem","anchor_text":"gy , pi to decision-making problem can be cast as ∑ ∑ ∑ ∑ e. max : ( ρtsbptsb + λtsell(Pts − ptsb) −","equation_id":"(2)-(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"s.t. \\sum_{b\\in B}p^{t}_{sb}\\leqslant P^{t}_{s} : \\upsilon^{t}_{s}, \\forall t\\in T \\quad (2)\np^{t}_{sb}\\geqslant 0 : \\omega^{t}_{sb}, \\forall b\\in B, \\forall t\\in T \\quad (3)"},{"evidence_id":"v141-b-g01-E21","location":{"location_id":"src-4c60176b12-p02-c1r2__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"Indices and sets V B Set of energy buyers pts S Set of energy sellers b The index of energy buyers ρ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Indices and sets B Set of energy buyers S Set of energy sellers b The index of energy buyers s The index of energy sellers T Set of time periods t Index of time periods Parameters \\Delta t Duration of period \\lambda^{t}_{sell} Feed-in Tariff in period t \\lambda^{t}_{cost} P2P transaction cost in period t \\lambda^{t}_{buy} The TLOU price of energy buyer b in period t \\lambda^{t}_{buy0} Initial electricity price in TLOU in period t k^{t} Constant coefficient in TLOU P^{t}_{s} The energy supply of seller s in period t D^{t}_{b} The energy demand of buyer b in period t \\eta_{c} Charging efficiency \\eta_{d} Discharging efficiency p^{u} Maximal charging/discharging power Q^{0}_{b} Initial energy storage level of buyer b Q_{m} Capacity of the shared energy storage units Variables p^{t}_{sb} P2P transaction amount between seller s and buyer b in period t \\rho^{t}_{sb} P2P transaction price between seller s and buyer b in period t p^{t}_{bg} Energy from the grid of buyer b in period t p^{t}_{bc} Charging power of buyer b in period t p^{t}_{bd} Discharging power of buyer b in period t Q_{b} Capacity allocation of buyer b Q^{t}_{b} Energy storage level of buyer b in period t"},{"evidence_id":"v141-b-g02-e008","location":{"location_id":"src-4c60176b12-p05-c1r3__v141-a-M01-participation","page":5,"printed_page":null,"section":"2.3 Aggregator","anchor_text":"tiple buyers share the capacity use right of the SES, which provides the er buyers with more flexibl","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"P2P transaction price should be no less than FiT and no higher than TLOU, otherwise, energy sellers/buyers will quit the P2P market."},{"evidence_id":"v141-b-g02-e024","location":{"location_id":"src-4c60176b12-p06-c2r3__v141-a-M01-pricing","page":6,"printed_page":null,"section":"3.3 Peer-to-peer market equilibrium problem","anchor_text":"For the first game, energy sellers want to maximize energy revenues ss and will increase the P2P tra","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"For the first game, energy sellers want to maximize energy revenues and will increase the P2P transaction price \\rho_{sb}^{t}. In contrast, energy buyers aim to minimize energy costs and will lower the P2P transaction price \\rho_{sb}^{t}. Considering the bargain between energy sellers and buyers in the P2P market, the transaction between peers can be described as a non-cooperative game. The first game equilibrium exists when considering energy sellers and buyers’ optimal problems simultaneously. The P2P transaction price \\rho_{sb}^{t} is an endogenous variable, which is not determined by a single participant unilaterally, but obtained from the market equilibria according to the supply and demand relationship. So the P2P transaction price can reflect the value of energy resources."},{"evidence_id":"v141-b-g02-e034","location":{"location_id":"src-4c60176b12-p08-c1r1__v141-a-M01-pricing","page":8,"printed_page":null,"section":"4.1 KKT conditions / P2P price","anchor_text":"B. Zheng et al. constraints. The P2P transaction price variable ρtsb is endogenously determined and ","equation_id":"(46)-(47)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"The P2P transaction price variable \\rho_{sb}^{t} is endogenously determined and the SES capacity is allocated by solving equilibrium (45). From the energy sellers’ side, according to equation (28), \\rho_{sb}^{t} can be calculated as follows: \\rho_{sb}^{t} = \\lambda_{sell}^{t} + \\lambda_{cost}^{t} + (\\upsilon_s^{t} - \\omega_{sb}^{t})/\\Delta t \\tag{46} From the energy buyers’ side, according to equation (32), \\rho_{sb}^{t} can be calculated as follows: \\rho_{sb}^{t} = -\\gamma_b^{t}/\\Delta t \\tag{47} The price in (46) and (47) are the same in the equilibrium problem (45), and thus the transaction price \\rho_{sb}^{t} mainly depends on the parameters and some dual variables."},{"evidence_id":"v141-b-g03-e01","location":{"location_id":"src-4c60176b12-p08-c1r1__v141-a-M01-pricing","page":8,"printed_page":null,"section":"4.1 KKT conditions / P2P price","anchor_text":"B. Zheng et al. constraints. The P2P transaction price variable ρtsb is endogenously determined and ","equation_id":"46","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"From the energy sellers’ side, according to equation (28), ρ^{t}_{sb} can be calculated as follows: ρ^{t}_{sb} = λ^{t}_{sell} + λ^{t}_{cost} + (υ^{t}_{s} − ω^{t}_{sb})/Δt    (46)"},{"evidence_id":"v141-b-g03-e02","location":{"location_id":"src-4c60176b12-p08-c1r1__v141-a-M01-pricing","page":8,"printed_page":null,"section":"4.1 KKT conditions / P2P price","anchor_text":"B. Zheng et al. constraints. The P2P transaction price variable ρtsb is endogenously determined and ","equation_id":"47","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"From the energy buyers’ side, according to equation (32), ρ^{t}_{sb} can be calculated as follows: ρ^{t}_{sb} = − γ^{t}_{b}/Δt    (47)"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing"],"extras":{"decision_anchor":"pricing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E09","quote":"The aggregator collects all participants’ supply and demand information and clears the P2P market. By solving the market equilibrium problem, it can provide P2P transaction price and amount between energy seller and buyer and capacity allocation among energy buyers."},{"evidence_id":"v141-b-g01-E23","quote":"The P2P transaction price and the amount and the SES capacity allocation are obtained from the market equilibrium."}],[{"evidence_id":"v141-b-g03-e04","quote":"In addition, in our model, ρ^{t}_{sb} must be no less than the λ^{t}_{sell} + λ^{t}_{cost}, otherwise, sellers will quit the P2P market. Similarly, ρ^{t}_{sb} must be no more than TLOU, otherwise, buyers will quit the P2P market."},{"evidence_id":"v141-b-g01-E13","quote":"Parameter \\lambda^{t}_{sell} is FiT when a seller sells its energy to the power grid. Parameter \\lambda^{t}_{cost} is the P2P transaction cost, including network tariff for using the physical grid facilities and aggregator service fee."}],[{"evidence_id":"v141-b-g03-e03","quote":"This P2P pricing mechanism is beyond the control of a single participant"}]],"C2_formalization":{"graph_sha256":"f8e513c6352bff71cc78b542465ada29bf73f7120cce6df4d01ecaea3658c1e4","applicability":"formalized","reason":"The source supplies explicit KKT-derived price equations (46)-(47) and the participation price bounds for the bilateral P2P transaction price. The clearing-to-pricing edge represents the equilibrium determination of the price and transaction allocation. B evidence remains unreviewed; this formalization is provisional and does not assert independent source verification.","bindings":[{"object_id":"v141-c-R008-x-rho","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"The P2P transaction price is the object of pricing.local; the frozen edge v141-c-R008-E001 links local clearing to local pricing and supports the equilibrium production of this price."},{"object_id":"v141-c-R008-x-p","node_ids":["clearing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"The P2P transaction amount is a clearing allocation stated in C001; it is represented through clearing.local and the same clearing-to-pricing relation."},{"object_id":"v141-c-R008-theta-Delta-t","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"The period duration appears in the seller-side and buyer-side price decompositions, so it binds to local pricing and the clearing-to-pricing relation."},{"object_id":"v141-c-R008-theta-lambda-sell","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"The feed-in tariff is a source-defined parameter forming the lower price component and the seller-side price expression."},{"object_id":"v141-c-R008-theta-lambda-cost","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"The P2P transaction cost is a source-defined parameter forming the lower price component and the seller-side price expression."},{"object_id":"v141-c-R008-theta-TLOU","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The TLOU price is the source-stated upper bound on the local P2P transaction price, so it binds directly to pricing.local."},{"object_id":"v141-c-R008-C001","node_ids":["clearing.local","pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"C001 is the existing clearing-to-pricing constraint and is supported by the frozen edge v141-c-R008-E001; the expression records the source's equilibrium price relations for the amount and price."},{"object_id":"v141-c-R008-C002","node_ids":["pricing.local"],"edge_ids":[],"rationale":"C002 is a bound on the local P2P transaction price and requires only the pricing.local node."},{"object_id":"v141-c-R008-C003","node_ids":["pricing.local"],"edge_ids":[],"rationale":"C003 is a property of the local P2P pricing mechanism; the equality of seller-side and buyer-side price expressions records that the price is not set unilaterally by one participant."}],"revision_requests":[]}},"quarantined_references":[]}});
